// ═══ WITHOUT generics (raw type) — ClassCastException at RUNTIME ═══
List rawList = new ArrayList();
rawList.add("Rajesh");
rawList.add(42);
String name = (String) rawList.get(1);  // ClassCastException! 42 is Integer!

// ═══ WITH generics — compile error BEFORE running ═══
List<String> safeList = new ArrayList<>();
safeList.add("Rajesh");
// safeList.add(42);  → COMPILE ERROR! Integer ≠ String. Caught early!

// ═══ GENERIC CLASS ═══
class AccountHolder<T> {
    private T account;
    public T getAccount() { return account; }
    public void setAccount(T account) { this.account = account; }
}
AccountHolder<SavingsAccount> holder = new AccountHolder<>();
holder.setAccount(new SavingsAccount());  // type-safe!

// ═══ GENERIC METHOD ═══
public <T> T findFirst(List<T> list) {
    return list.isEmpty() ? null : list.get(0);
}
String first = findFirst(List.of("A", "B"));  // T inferred as String

// ═══ BOUNDED TYPE PARAMETER ═══
public <T extends Number> double sum(List<T> numbers) {
    return numbers.stream().mapToDouble(Number::doubleValue).sum();
}
sum(List.of(1, 2, 3));        // T = Integer (extends Number) ✅
sum(List.of(1.5, 2.5));       // T = Double (extends Number) ✅
// sum(List.of("a", "b"));    // COMPILE ERROR! String not extends Number!

// ═══ WILDCARDS + PECS ═══
// ? extends T — PRODUCER (read FROM it, can't write TO it)
public double totalBalance(List<? extends Account> accounts) {
    // Can READ: Account acc = accounts.get(0);  ✅ (could be Savings or Current)
    // Can't WRITE: accounts.add(new SavingsAccount());  ❌ (might be List<CurrentAccount>!)
    return accounts.stream().mapToDouble(Account::getBalance).sum();
}

// ? super T — CONSUMER (write TO it, can't read specific type FROM it)
public void addDefaults(List<? super SavingsAccount> list) {
    list.add(new SavingsAccount());  // ✅ can write SavingsAccount!
    // Object obj = list.get(0);     // can only read as Object (don't know exact type)
}

// ═══ PECS SUMMARY ═══
// Producer: ? extends T → get/read T from it
// Consumer: ? super T   → put/write T into it
// Both:     T            → read and write
// Collections.copy signature:
// public static <T> void copy(List<? super T> dest, List<? extends T> src)
//                               CONSUMER (write)       PRODUCER (read)
```

